            padding: 12px 24px;
            background: #e0e0e0;
            color: #333;
            border: none;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: background 0.3s;
        }

        .logout-btn:hover {
            background: #d0d0d0;
        }

        /* 响应式 */
        @media (max-width: 480px) {
            .container {
                padding: 30px 20px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- 登录表单 -->
        <div class="login-form" id="loginForm">
            <div class="logo">
                <h1>邮箱登录</h1>
            </div>

            <form id="form">
                <div class="form-group">
                    <label for="email">邮箱地址</label>
                    <input type="email" id="email" placeholder="请输入邮箱地址" required>
                    <div class="error-message" id="emailError">请输入有效的邮箱格式</div>
                </div>

                <div class="form-group">
                    <label for="password">密码</label>
                    <div class="password-wrapper">
                        <input type="password" id="password" placeholder="请输入密码" required>
                        <span class="password-toggle" id="passwordToggle">👁</span>
                    </div>
                    <div class="error-message" id="passwordError">请输入密码</div>
                </div>

                <button type="submit" class="login-btn" id="loginBtn">登录</button>
            </form>
        </div>

        <!-- 登录成功后的仪表盘 -->
        <div class="dashboard" id="dashboard">
            <div class="welcome">欢迎回来！</div>
            <div class="user-info">
                <p><strong>登录账号：</strong><span id="userEmail"></span></p>
                <p><strong>登录时间：</strong><span id="loginTime"></span></p>
            </div>
            <button class="logout-btn" id="logoutBtn">退出登录</button>
        </div>
    </div>

    <script>
        // 配置
        const VALID_EMAIL = 'demo@example.com';
        const VALID_PASSWORD = 'demo123';

        // DOM 元素
        const loginForm = document.getElementById('loginForm');
        const dashboard = document.getElementById('dashboard');
        const form = document.getElementById('form');
        const emailInput = document.getElementById('email');
        const passwordInput = document.getElementById('password');
        const emailError = document.getElementById('emailError');
        const passwordError = document.getElementById('passwordError');
        const passwordToggle = document.getElementById('passwordToggle');
        const loginBtn = document.getElementById('loginBtn');
        const logoutBtn = document.getElementById('logoutBtn');
        const userEmail = document.getElementById('userEmail');
        const loginTime = document.getElementById('loginTime');

        // 初始化检查登录状态
        function checkLoginStatus() {
            const isLoggedIn = localStorage.getItem('isLoggedIn');
            const storedEmail = localStorage.getItem('userEmail');
            const loginTimestamp = localStorage.getItem('loginTime');

            if (isLoggedIn === 'true' && storedEmail) {
                showDashboard(storedEmail, loginTimestamp);
            }
        }

        // 显示错误
        function showError(input, errorElement, message) {
            input.classList.add('error');
            errorElement.textContent = message;
            errorElement.classList.add('show');
        }

        // 清除错误
        function clearError(input, errorElement) {
            input.classList.remove('error');
            errorElement.classList.remove('show');
        }

        // 验证邮箱格式
        function validateEmail(email) {
            const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            return regex.test(email);
        }

        // 显示仪表盘
        function showDashboard(email, timestamp) {
            loginForm.classList.add('hidden');
            dashboard.classList.add('show');
            userEmail.textContent = email;
            loginTime.textContent = timestamp || new Date().toLocaleString();
        }

        // 显示登录表单
        function showLoginForm() {
            dashboard.classList.remove('show');
            loginForm.classList.remove('hidden');
            form.reset();
        }

        // 登录处理
        form.addEventListener('submit', function(e) {
            e.preventDefault();

            const email = emailInput.value.trim();
            const password = passwordInput.value;

            // 清除之前的错误
            clearError(emailInput, emailError);
            clearError(passwordInput, passwordError);

            // 验证邮箱格式
            if (!validateEmail(email)) {
                showError(emailInput, emailError, '请输入有效的邮箱格式');
                return;
            }

            // 验证密码
            if (!password) {
                showError(passwordInput, passwordError, '请输入密码');
                return;
            }

            // 模拟登录验证
            if (email === VALID_EMAIL && password === VALID_PASSWORD) {
                // 登录成功
                const loginTimestamp = new Date().toLocaleString();
                localStorage.setItem('isLoggedIn', 'true');
                localStorage.setItem('userEmail', email);
                localStorage.setItem('loginTime', loginTimestamp);

                showDashboard(email, loginTimestamp);
            } else {
                // 登录失败
                showError(passwordInput, passwordError, '账号或密码错误');
            }
        });

        // 密码显示/隐藏切换
        passwordToggle.addEventListener('click', function() {
            if (passwordInput.type === 'password') {
                passwordInput.type = 'text';
                passwordToggle.textContent = '🙈';
            } else {
                passwordInput.type = 'password';
                passwordToggle.textContent = '👁';
            }
        });

        // 退出登录
        logoutBtn.addEventListener('click', function() {
            localStorage.removeItem('isLoggedIn');
            localStorage.removeItem('userEmail');
            localStorage.removeItem('loginTime');
            showLoginForm();
        });

        // 实时清除错误
        emailInput.addEventListener('input', function() {
            clearError(emailInput, emailError);
        });

        passwordInput.addEventListener('input', function() {
            clearError(passwordInput, passwordError);
        });

        // 页面加载时检查登录状态
        checkLoginStatus();
    </script>
</body>
</html>
